fn policy_state_json(account: &validation_program_client::accounts::PolicyStateZc) -> Value {
	json!({
		"bump": account.bump,
		"minimum": account.minimum.get(),
		"maximum": account.maximum.get(),
		"required_approvals": account.required_approvals,
	})
}

fn print_value(json_output: bool, name: &str, address: &Pubkey, value: &Value) {
	if json_output {
		println!(
			"{}",
			serde_json::to_string_pretty(value).unwrap_or_default()
		);
		return;
	}

	println!("{name} {address}");
	if let Some(fields) = value.as_object() {
		for (key, value) in fields {
			println!("  {key}: {value}");
		}
	}
}
